-- Migration 130: Academy — the 176-task training curriculum.
--
-- Loads the real Indulge Retail Training task register (176 requests, 17 training
-- days, 4-27 July 2026) as playable drills, mapped onto the 50-group ladder.
--
-- Structure (mirrors lib/academy/curriculum.ts — keep them in step):
--   groups 1-26  -> 4 tasks each (tasks 1-104)
--   groups 27-50 -> 3 tasks each (tasks 105-176)
--   tiers: 1-10 easy | 11-25 medium | 26-40 advanced | 41-50 expert
--   day_number = 1-based index of the task's real date within its group
--
-- Depends on 129 (tiers + curriculum columns).
--
-- ALL CONTENT IS SYNTHETIC-SAFE: the register was scrubbed of member names,
-- addresses and contact details before authoring, and the generator refuses to
-- emit SQL if an email / phone / long digit-run appears in any field.
--
-- RE-RUN SAFE: guarded by WHERE NOT EXISTS on task_number.

INSERT INTO public.scenario_seeds
  (title, archetype, vertical, opening_message, hidden_constraints, difficulty,
   escalation_trigger, ideal_outcome, rubric_weights,
   group_number, day_number, task_number, task_date, raised_by, brief)
SELECT * FROM (VALUES
('Xiaomi Smart Camera C500 Pro — 1 pc', 'Comparison shopper, wants one answer not a spreadsheet', 'Shop', 'Hi, {{name}} here. I want one Xiaomi Smart Camera C500 Pro. I am told it is far cheaper in Bangkok than here, so can you check both India and Bangkok for me and tell me which way I should actually buy it.', '[{"id":"carrier_available","label":"Someone is flying back from Bangkok","reveal_when":"intern asks how the member would take delivery of a Bangkok purchase","value":"A colleague is flying back from Bangkok at the end of the week and would carry it, so a Bangkok purchase is genuinely viable rather than theoretical"},{"id":"warranty_decides","label":"Indian warranty is the deciding factor","reveal_when":"intern asks what matters most or raises the warranty difference between the two markets","value":"If the Bangkok unit cannot be serviced under warranty in India, the member will pay the higher Indian price without hesitating"},{"id":"real_photo","label":"Wants proof of actual stock","reveal_when":"intern offers to send product information or a listing","value":"He has been sent catalogue images before and wants a photograph of the unit physically sitting in the shop, not a product page"}]'::jsonb, 'easy', 'Member loses patience if the intern returns two listing prices side by side with no recommendation, or quotes a Bangkok price without saying whether the warranty travels.', 'Intern surfaces the hand-carry route and the warranty test, verifies live stock with a real photograph from the shop, and closes with one recommended purchase route carrying a landed price, warranty position and delivery date.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 1, 1, 1, '2026-07-04'::date, 'Anishqa', 'Check availability in India and Bangkok, confirm pricing in both, share best sourcing option (retail + online), delivery timeline, warranty differences, fastest option and real-time images. Follow-up: check the Xiaomi store in Bangkok for cost and availability.'),
('Stress-test the trainees', 'Rapid-fire member, drops everything at once', 'Global', '{{name}} here, apologies for the barrage. I need a table for four tonight, a car to the airport in the morning, a birthday gift for a colleague by {{date}}, and someone to tell me whether my visa paperwork is still sitting with your team. All of it today please.', '[{"id":"true_priority","label":"Only one of the four is actually urgent","reveal_when":"intern asks which of the requests matters most today","value":"Only the airport car genuinely cannot slip, everything else can comfortably land by tomorrow morning"},{"id":"gift_context","label":"The gift is a farewell, not a birthday","reveal_when":"intern asks who the gift is for","value":"The colleague is leaving the firm that week, so the member wants something personal rather than the usual corporate gesture"},{"id":"papers_on_file","label":"Visa paperwork was already submitted","reveal_when":"intern checks the file before asking the member to resend anything","value":"He sent the visa documents to the team a fortnight ago and will be visibly annoyed to be asked for them again"}]'::jsonb, 'easy', 'Member becomes terse if any one of the four requests goes unacknowledged, or if the intern fires back four separate replies instead of one consolidated list with an ETA against each.', 'Intern replies once, restates all four requests with an owner and an ETA each, establishes the airport car as the only hard commitment, and finds the visa paperwork already on file rather than asking for it twice.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 1, 1, 2, '2026-07-04'::date, 'Advita', 'Queens, Vikram and Savio to each throw 10–20 requests at the group to gauge how ready every trainee is.'),
('Four luxury watches for a repeat buyer', 'Seasoned collector, buys in multiples, little patience for vagueness', 'Legacy', 'Good morning, {{name}} here. I am adding four pieces to the collection this quarter, one Patek and three Audemars from the current line. Brand new and unworn only, full set with papers and box, and I will want the year of billing on each before I commit to anything.', '[{"id":"billing_year","label":"Year of billing is the real test","reveal_when":"intern asks why the year of billing matters to him","value":"He was once sold a piece billed three years earlier as new, and now treats the billing year as the deal breaker on every acquisition"},{"id":"viewing_first","label":"No money moves before a viewing","reveal_when":"intern asks about mode of payment or the payment timeline","value":"He will settle in full by bank transfer on the day, but will not release anything before a physical viewing of the actual pieces"},{"id":"partial_fill","label":"A staged fill is acceptable","reveal_when":"intern asks whether all four must land together","value":"Two now and two by the end of the quarter is perfectly acceptable, so nothing should be held back waiting for a complete set"}]'::jsonb, 'easy', 'Member disengages if prices are quoted before the pieces are confirmed unworn and fully papered, or if he is handed four dealers and asked to choose between them.', 'Intern returns one consolidated sheet covering price, lead time, year of billing, warranty validity and payment terms for each piece, establishes that a staged fill is fine, and secures a viewing before any money moves.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 1, 1, 3, '2026-07-04'::date, 'Vikram', 'Patek Philippe Nautilus 5712R-001; AP Code 11.59 26393NR.OO.A002KB.01; AP Code 11.59 26394OR.OO.D027KB.01; AP Code 11.59 Chronograph 26393OR.OO.A028CR.01. For each: reference number, cost, delivery time, year of billing, warranty validity, mode of payment and payment timeline. Brand new unused pieces only, with all papers and box.'),
('Vietnam family group tour — draft itinerary', 'Family organiser, planning for a crowd', 'Global', 'Hello, {{name}} here. We are twelve adults and one seven year old going to Vietnam, flying out on the fifteenth of October. I want four nights in total, two in Hanoi and two somewhere else worth seeing. Can you draft the itinerary.', '[{"id":"gentle_pace","label":"Four of the party are elderly","reveal_when":"intern asks about the make-up of the group or anyone with mobility needs","value":"Four of the twelve are in their seventies and cannot manage long walks or early starts, so the whole pace has to be gentle"},{"id":"second_stop_ruled_out","label":"Halong Bay is already ruled out","reveal_when":"intern proposes the second location or asks whether anywhere is off the list","value":"Half the group did Halong Bay two years ago, so the second stop has to be somewhere none of them have been"},{"id":"rooming","label":"Rooming split is fixed","reveal_when":"intern asks how the group needs to be roomed","value":"They need six twin rooms and one family room and will not be split across two hotels in the same city"}]'::jsonb, 'easy', 'Member pushes back if he receives a bare four night skeleton with no hotels, no costs and no ETA, or is asked to choose the second city himself.', 'Intern establishes the group profile, the gentle pace and the rooming split, then returns one recommended four night itinerary naming the second stop, with hotels held on option, per-head costing and a date by which the group must confirm.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 1, 1, 4, '2026-07-04'::date, 'Anishqa', '12 adults + 1 child (7 yrs). Hanoi 2 nights plus a second location for 2 nights, 4 nights total. Travel date 15 October.'),
('Adopt client-grade communication', 'Exacting member, judges the packaging as much as the answer', 'GMR', 'Hi {{name}}. I have just read the update your team sent me and I honestly could not get through it. Raw links, no prices, and nothing anywhere telling me what you would actually recommend. Can I have that again, properly.', '[{"id":"reads_on_phone","label":"Reads everything on his phone between meetings","reveal_when":"intern asks how the member prefers to receive updates","value":"He reads everything on his phone between meetings and will not open a long attachment or a spreadsheet, so it has to work as a message"},{"id":"wants_a_pick","label":"Wants a decision, not a tidier menu","reveal_when":"intern asks what would make the update genuinely useful","value":"He does not want the same shortlist re-sent looking neater, he wants the team to name the one option they would choose and say why"}]'::jsonb, 'easy', 'Member disengages if the intern apologises and resends the same content with better formatting but still no recommendation, or defends the original message.', 'Intern owns it without excuses, rewrites the update as a short phone-readable message carrying price, location and link inline, and closes with a single clear recommendation and the next step he needs to take.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 2, 1, 5, '2026-07-04'::date, 'Savio', 'Share details the way you would with a client: shorten links, bold key words, add emojis. Proactively review other concierge managers'' conversations to learn tone and approach.'),
('Goa lunch restaurant recommendations — today', 'Hungry member on a tight clock, wants it settled now', 'Global', '{{name}} here. Three of us need lunch today and we want to be sitting down by one, somewhere around Assagao rather than Panjim. Send me where to go, and please make sure the place is actually open.', '[{"id":"vegan_guest","label":"One of the three is vegan","reveal_when":"intern asks about dietary requirements for the table","value":"One of the three is vegan, so a menu offering nothing beyond a paneer dish will not do"},{"id":"drive_limit","label":"Will not drive more than twenty minutes","reveal_when":"intern asks where the member is coming from or how far he will travel","value":"They are staying near Anjuna and will not drive more than twenty minutes for lunch"},{"id":"monsoon_shut","label":"His usual choices are shut","reveal_when":"intern asks whether the member already has somewhere in mind","value":"The two places he would normally book are closed for the monsoon, which is exactly why he is asking the team"}]'::jsonb, 'easy', 'Member turns short if he is sent three links and asked to pick, or if somewhere is recommended without anyone having rung to confirm it is open and can seat them by one.', 'Intern rings ahead to confirm opening and a table by one, recommends a single place that suits the vegan guest and sits inside the drive limit, and sends the distance, menu and booking confirmation together in one message.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 2, 2, 6, '2026-07-06'::date, 'Savio', '3 pax, table needed by 1:00 PM, around Assagao (not Panjim). Share links, images, distance from location and menu. Verify the restaurant is actually open.'),
('Finish mock drills by 3:00 PM', 'Deadline-setter, measures the team by the clock', 'GMR', '{{name}} here. I go into meetings from three and I want every open request of mine either closed or clearly answered before then. Send me the list of what is outstanding and who is on each one.', '[{"id":"two_will_slip","label":"Two items genuinely cannot close today","reveal_when":"intern is honest about what will not land and asks whether that is acceptable","value":"He will accept two items slipping to tomorrow provided he is told now rather than discovering it at three o''clock"},{"id":"written_not_call","label":"Wants it in writing, not a call","reveal_when":"intern offers to ring the member to run through it","value":"He does not want a call, he wants one written list he can forward straight to his assistant"}]'::jsonb, 'easy', 'Member escalates if he gets a partial list, a blanket assurance that everything is in hand with no per-item detail, or finds out at three that something quietly slipped.', 'Intern sends one written list of every open item with owner, current status and a stated time, flags honestly the two that will not close today, and delivers the rest before three without being chased.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 2, 2, 7, '2026-07-06'::date, 'Advita', 'After that, Advita, Ananyshree and Anishqa will all drop requests and grade on Freshdesk usage, quality of response, resolution and behaviour under 10 simultaneous requests.'),
('Flight — Goa to Hyderabad, 15 July', 'Frequent flyer, knows what he wants, no browsing', 'Global', 'Hi, {{name}} here. I need to be in Hyderabad on the fifteenth. Morning out of Goa, non-stop only, and send the fare with it.', '[{"id":"arrival_cutoff","label":"Must be on the ground before eleven","reveal_when":"intern asks how early the member needs to arrive or what is driving the timing","value":"There is a site visit at midday, so anything landing after eleven is useless to him"},{"id":"equipment_bags","label":"Travelling with equipment","reveal_when":"intern asks about baggage","value":"He is carrying two large cases of equipment, so the fare has to be quoted with checked baggage included rather than as a base fare"},{"id":"same_day_return","label":"A return leg is also needed","reveal_when":"intern asks whether this is one way or a return","value":"He also needs to come back the same evening but did not think to mention it"}]'::jsonb, 'easy', 'Member is irritated by a routing with a layover, a fare quoted without baggage, or a screenshot of a search page sent in place of a recommendation.', 'Intern confirms the arrival cut-off and uncovers the return leg, recommends one non-stop morning departure with the all-in fare including checked baggage, and holds or books it with written confirmation.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 2, 2, 8, '2026-07-06'::date, 'Savio', 'Morning departures, non-stop only, with fare.'),
('London countryside stay — one night', 'Romantic idea, unrealistic budget, needs steering', 'Global', 'Hello {{name}}. I want one night in a proper old castle in the English countryside, somewhere genuinely beautiful. Budget is around a hundred pounds for the room. Photos of the room and a map pin please.', '[{"id":"budget_flex","label":"Budget will stretch for the right property","reveal_when":"intern explains what a hundred pounds realistically buys and asks whether there is room to move","value":"He will go to three times that figure for a genuine castle, the number was a guess rather than a limit"},{"id":"date_flex","label":"The night is movable","reveal_when":"intern asks which night it is for","value":"The date is not fixed, and shifting it midweek would open up far better properties at far better rates"},{"id":"no_car","label":"Not hiring a car","reveal_when":"intern asks how the member intends to get there","value":"They are not driving, so the property has to be reachable by train with a transfer arranged at the other end"}]'::jsonb, 'easy', 'Member is unimpressed by a list of budget country inns dressed up as castles, or by being told his budget is impossible with nothing offered in its place.', 'Intern tests the budget and the date gently, recommends one genuine castle stay that works midweek, and sends room photographs, the all-in price, the map pin and the transfer plan together in a single message.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 3, 1, 9, '2026-07-06'::date, 'Anishqa', 'A beautiful old castle in the countryside, hotel price around £100 max. Share room photos and Google Maps link.'),
('Porter pickup and drop — Mumbai', 'Practical member, wants a number and a time', 'House', '{{name}} here. I need a pickup from my flat in the northern suburbs and a drop at a friend''s place in Bandra today. Book it and tell me what it will cost and when it will reach.', '[{"id":"fragile_item","label":"It is a large fragile item, not a parcel","reveal_when":"intern asks what is actually being moved","value":"It is a framed mirror rather than a box, so a two wheeler booking is useless and it needs a tempo with someone to help lift it"},{"id":"evening_window","label":"Recipient is only home in the evening","reveal_when":"intern asks when the drop needs to happen","value":"The friend is only home after seven, so an immediate pickup with an afternoon drop would simply fail"},{"id":"no_driver_calls","label":"Do not route the driver to him","reveal_when":"intern asks who the driver should coordinate with","value":"He is in meetings all afternoon and wants the team to handle the driver rather than having calls put through to him"}]'::jsonb, 'easy', 'Member is annoyed if the wrong vehicle class is booked, if a fare is quoted with no pickup time or drop ETA, or if he is asked to speak to the driver himself.', 'Intern establishes what is being moved and the evening drop window, books the correct vehicle with help to lift, and returns one message carrying the fare, the pickup time, the drop ETA and confirmation that the team will run the driver.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 3, 1, 10, '2026-07-06'::date, 'Savio', 'Pickup: C wing, Flat 404, Shalom Paradise, Mira Road East 401107. Drop: Flat 602, Wing A, Sandhu Palace, Nargis Dutt Road, Pali Hill, Bandra West 400050. Confirm cost and ETA, use the correct location.'),
('Jasprit''s sportswear — standby suppliers', 'Professional athlete, judges the team purely on turnaround', 'Shop', 'Hi {{name}}. I play cricket professionally and I keep getting caught short on kit when I travel, spikes, shoes, socks. I want standby suppliers in India and the UK who can turn something around same day or by the next morning. Start me off with the bowling spikes.', '[{"id":"exact_model","label":"Model must be confirmed from a photograph","reveal_when":"intern asks the member to confirm the exact model rather than assuming it","value":"Two bowling spike models look near identical and he will send a photograph of his current pair if asked, but guessing between them will waste the order"},{"id":"dual_sizing","label":"Sizes differ across EU and UK charts","reveal_when":"intern asks for his size in both EU and UK scales","value":"He takes a different nominal size on the EU and UK charts and has been sent the wrong one before, so both numbers must be captured before anything is ordered"},{"id":"uk_first","label":"He is in the UK next week","reveal_when":"intern asks where the member will be over the coming weeks","value":"He flies to the UK next week, so the UK supplier is the urgent one and the Indian standby can follow"}]'::jsonb, 'easy', 'Member loses confidence if the intern orders against an assumed model or a single size chart, or comes back with a list of shops rather than a named supplier who has confirmed the turnaround in writing.', 'Intern requests the model photograph and both size scales before ordering, names one standing supplier in each market with a confirmed same-day or next-morning commitment, and prioritises the UK given the travel.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 3, 1, 11, '2026-07-06'::date, 'Anishqa', 'Standby cricket goods suppliers in India and the UK (spikes, shoes, socks) and anywhere he travels, for same-day / next-morning turnaround. Confirm the exact Adidas bowling spikes model via photo before sourcing. EU and UK sizes to come from Megh.'),
('Where to eat after the Argentina–Egypt match', 'Match-night member, expects the team to already know his taste', 'Global', '{{name}} here. We are coming out of the Argentina match tonight and will want to eat straight after. Pick somewhere for us, you know what I like by now.', '[{"id":"preference_on_file","label":"His preference is already on the file","reveal_when":"intern checks the member history before asking any preference question","value":"The file already records that he eats no red meat and favours Japanese, so asking him again reads as the team not knowing him"},{"id":"late_kitchen","label":"Kitchens will mostly have closed","reveal_when":"intern asks what time they will actually clear the ground","value":"They will not be out until close to eleven, so most kitchens will have shut and the place has to be verified as still serving"},{"id":"walkable","label":"Wants to walk, not drive","reveal_when":"intern asks how far the member is prepared to travel afterwards","value":"He wants somewhere within walking distance of the ground because the roads around it will be gridlocked"}]'::jsonb, 'easy', 'Member reacts badly to being asked whether he eats meat or what cuisine he likes, and to any recommendation sent without the distance from the ground or a confirmed late kitchen.', 'Intern reads the file instead of asking, recommends one late-serving Japanese option within walking distance of the ground, confirms with the restaurant that the kitchen is open at that hour, and holds the table.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 3, 1, 12, '2026-07-06'::date, 'Advita', 'Must be mapped to the member''s known taste — check the backend for cuisine preference and veg/non-veg before recommending. Include location and distance.'),
('Braille tutor — home visit', 'Private learner, quietly determined, dislikes fuss', 'House', 'Hello, {{name}} here. I would like to learn braille and I would rather not go to a centre for it. Can you find me a tutor who will come to the house.', '[{"id":"for_himself","label":"The lessons are for the member himself","reveal_when":"intern asks gently who the lessons are for","value":"It is for the member himself following a change in his eyesight, which is why he wants it handled privately at home"},{"id":"early_only","label":"Only early mornings work","reveal_when":"intern asks about timings and how often he wants to learn","value":"Only before eight in the morning works, twice a week, and he wants the same tutor every session rather than a rota"},{"id":"script","label":"Wants Bharati braille alongside English","reveal_when":"intern asks which script or language he wants to learn in","value":"He wants Bharati braille as well as English, which narrows the pool of qualified tutors considerably"}]'::jsonb, 'easy', 'Member withdraws if he is handed a list of institutes to ring himself, or if the reason behind the request is handled clumsily or asked about bluntly.', 'Intern asks with care, uncovers that it is for the member and the early-morning and script constraints, and returns one or two vetted tutors with credentials, confirmed home visits, fees and a proposed first session date.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 4, 1, 13, '2026-07-06'::date, 'Advita', 'Member wants to learn braille; find a tutor who can come home.'),
('Laptop upgrade advice', 'Loyal to what he knows, wants to be told what to buy', 'Shop', 'Hi {{name}}. I have used a Mac for years and I keep reading about these new machines with the AI chips. Is it worth me waiting, or do I just replace mine now. Tell me what to buy.', '[{"id":"video_editing","label":"He edits video most evenings","reveal_when":"intern asks what the member actually does on the machine","value":"He edits video most evenings and everything else is email, which makes memory and screen matter far more to him than the chip branding"},{"id":"always_travelling","label":"Carries it constantly","reveal_when":"intern asks about portability or how he works day to day","value":"He travels most weeks and will not carry anything heavy or anything that needs charging halfway through a flight"},{"id":"machine_failing","label":"The current machine is dying","reveal_when":"intern asks whether he can realistically afford to wait","value":"His current machine no longer holds charge, so waiting six months for the next launch is not an option however good it might be"}]'::jsonb, 'easy', 'Member is frustrated by a comparison of three machines with a request to pick one, or by marketing language about AI chips that says nothing about how he actually works.', 'Intern establishes the editing workload, the travel and the failing battery, names one machine in one specific configuration, says plainly whether waiting is worth it, and offers to source it with a price and delivery date.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 4, 1, 14, '2026-07-06'::date, 'Advita', 'Long-time Mac user. Explain the new AI-chip devices, whether it is worth waiting, and the difference versus the latest Mac. End with a clear recommendation, not options.'),
('Source a Whoop charger', 'Terse member, one line and gone', 'Shop', '{{name}} here. Need a Whoop charger.', '[{"id":"band_generation","label":"It is the older band","reveal_when":"intern asks which generation or model of band he wears","value":"It is the previous generation band, and the charger currently on general sale will not fit it"},{"id":"battery_flat","label":"The band is already dead","reveal_when":"intern asks when he needs it by","value":"The band went flat this morning, so anything arriving in a week is pointless and a local pickup or a loaner would be far better"},{"id":"not_at_home","label":"He is not at the address on file","reveal_when":"intern asks where it should actually be delivered","value":"He is in Goa for the fortnight, not at the home address the team holds on file"}]'::jsonb, 'easy', 'Member goes quiet on the intern if the reply is a bare acknowledgement with no question and no ETA, or if a charger is ordered to the address on file without anyone checking where he is.', 'Intern asks the two questions that matter, which generation and where he actually is, in one message with an ETA attached, finds a same-day route for the correct model, and tracks the delivery through rather than leaving him to chase it.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 4, 1, 15, '2026-07-06'::date, 'Advita', 'Source a Whoop charger.'),
('Convenient 3-day international trip', 'Spontaneous traveller, low tolerance for admin', 'Dubai', 'Hi, {{name}} here. I want to get out of the country for three days around {{date}}, nothing complicated. Give me a couple of ideas with the cost per head.', '[{"id":"visa_position","label":"Only the UAE visa is live","reveal_when":"intern asks what visas the member currently holds in his passport","value":"The only valid visa he holds is for the UAE, so anywhere requiring a fresh application will not happen in the time available"},{"id":"party_of_four","label":"Four people, not one","reveal_when":"intern asks how many are travelling","value":"There are four of them going together, which changes both the costing and the kind of hotel that will work"},{"id":"no_repeat","label":"Wants more than the usual Dubai run","reveal_when":"intern proposes a destination and asks whether he has been recently","value":"He has done the standard Dubai weekend twice already and wants something in the region that does not feel like a repeat of it"}]'::jsonb, 'easy', 'Member disengages if he is sent five destinations with no costing attached, or if somewhere is proposed without anyone having checked which visa he actually holds.', 'Intern establishes the visa position and the party of four, recommends one three day Gulf itinerary that avoids repeating the usual Dubai weekend, and quotes an all-in per-head cost covering flights, hotel and transfers.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 4, 1, 16, '2026-07-06'::date, 'Advita', 'Simple and convenient; give suggestions with cost per head.'),
('Gift for brother''s birthday — 27 July', 'Expects recall, will not brief the team twice', 'Shop', '{{name}} here. It is my brother''s birthday on the twenty-seventh and I want to give him something cool. You have done gifts for him before, so please do not make me go through it all again.', '[{"id":"profile_on_file","label":"The brother''s profile is already on file","reveal_when":"intern shows he has checked the history before asking anything at all","value":"The file already carries the brother''s age, his watch collecting and what was sent last year, and the member will not repeat a word of it"},{"id":"budget_moved","label":"The budget has moved up this year","reveal_when":"intern confirms the budget rather than quietly assuming last year''s figure","value":"He will spend roughly double what he spent last year because this is a milestone birthday for his brother"},{"id":"gift_must_travel","label":"The gift has to travel","reveal_when":"intern asks where the gift actually needs to reach","value":"His brother is abroad until the end of the month, so it has to be delivered to him there or held and handed over the day he lands"}]'::jsonb, 'easy', 'Member becomes curt the moment he is asked his brother''s age, his interests or his budget, every one of which the team already holds on file.', 'Intern opens by referencing what is already on file, confirms only the raised budget and the delivery location, recommends one distinctive gift rather than a shortlist, and commits to a delivery date safely ahead of the birthday.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 5, 1, 17, '2026-07-06'::date, 'Advita', 'Something cool; budget and profile to be established by the team, not asked repeatedly.'),
('Two wine chillers with lock — Kolkata', 'Fit-out client, dimensions are non-negotiable', 'House', 'Hello {{name}}. I need two wine chillers for the cabinetry at the house in Kolkata. They have to fit the recess in the drawing I sent across, and both must lock. Find them and send me vendor details.', '[{"id":"not_snug","label":"Smaller is fine, snug is not","reveal_when":"intern confirms the recess dimensions and asks about tolerance","value":"A unit smaller than the recess is fine, but anything that fits snugly will not clear the ventilation gap the carpenter has left behind it"},{"id":"capacity_limit","label":"Only a fifteen bottle unit fits","reveal_when":"intern asks about capacity or proposes one larger unit instead of two","value":"Only a fifteen bottle unit clears the height, which is exactly why two are needed rather than one large one"},{"id":"lock_reason","label":"The lock is the whole point","reveal_when":"intern asks why the lock matters or offers a model without one","value":"There are teenagers in the house, so a model without a working key lock is not a candidate at any price"}]'::jsonb, 'easy', 'Member reacts sharply if a model is put forward without its dimensions checked against the drawing, or if a unit with no lock is sent through as an option at all.', 'Intern confirms the recess dimensions and the ventilation tolerance in writing, shortlists only lockable fifteen bottle units that clear it, and returns two vendor quotes with dimensions, price, warranty and a Kolkata delivery date.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 5, 1, 18, '2026-07-06'::date, 'Anishqa', 'Must fit the space marked in the cabinet drawing (PDF shared) — can be smaller but not a snug fit. Lock is mandatory. Later refined: only a 15-bottle unit fits, two units needed, dimensions to be confirmed. Share vendor details.'),
('Log all tasks in Freshdesk', 'Systems-minded member, wants a paper trail', 'GMR', 'Hi {{name}}. I have raised a fair few things with your team this week and I have no idea where any of them stand. Can I get one proper status list, and can it stay updated so I am not the one asking again.', '[{"id":"unlogged_items","label":"Two requests were never logged","reveal_when":"intern reconciles the list against the conversation rather than reporting from memory","value":"Two of the things he raised were never logged anywhere and will only surface if the intern goes back through the thread properly"},{"id":"copy_assistant","label":"His assistant should get the updates","reveal_when":"intern asks who else should be kept informed going forward","value":"He wants his assistant copied on the status from now on so that he stops being the one doing the chasing"}]'::jsonb, 'easy', 'Member loses trust if the list comes back shorter than what he actually raised, or if he is told everything is being worked on with no status or time attached to each item.', 'Intern reconstructs the full list from the thread, catches the two requests that were never logged, returns one status line per item with an owner and a stated time, and sets a standing update going to both the member and his assistant.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 5, 1, 19, '2026-07-06'::date, 'Advita', 'Add the tasks into FD so the team knows what to do and how to check status.'),
('Consolidated PDF of yesterday''s requests', 'Decision-maker who wants one document, not a thread', 'GMR', '{{name}} here. I am not scrolling back through yesterday''s thread to work out where everything stands. Put every request I raised yesterday into one document, with status against each, so I can actually take a decision on it.', '[{"id":"decision_deadline","label":"Decision sits before a call","reveal_when":"intern asks when the document is needed or why it matters today","value":"There is an internal call at half past eleven this morning - the document is of no use to them after that"},{"id":"cost_and_owner","label":"Costs and owners must be on every line","reveal_when":"intern asks what the document should contain or proposes a structure","value":"Every line needs an indicative cost and a named owner - a list of request titles alone will be sent straight back"},{"id":"pdf_on_phone","label":"A single PDF, not a spreadsheet","reveal_when":"intern asks about format or offers a shared link","value":"It must be one PDF they can read on a phone between meetings - a shared spreadsheet will not be opened"}]'::jsonb, 'easy', 'Member loses patience if the reply is an empty acknowledgement with no time attached, or if the team asks them to restate requests the group already logged yesterday.', 'Surface the half past eleven deadline, the cost-and-owner requirement and the phone-readable PDF format, commit to a specific delivery time inside that window, and send one consolidated document rather than a run of fragmented updates.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 5, 2, 20, '2026-07-07'::date, 'Advita', 'One document covering every request from the previous day so a decision can be taken.'),
('Cost of a Rolex ''Panda''', 'Sceptical buyer testing whether the team has genuine retail access', 'Shop', 'Morning, {{name}} here. What is the Rolex Panda going for at the moment. And be straight with me - can your team actually get one out of the boutique at retail, or are we talking grey market.', '[{"id":"premium_limit","label":"Secondary market only with papers","reveal_when":"intern asks what the member will accept on source or on premium over retail","value":"They will consider a secondary-market piece only if it is unworn with box and papers, and they will not pay more than a modest premium over retail"},{"id":"willing_to_wait","label":"Prepared to wait for an allocation","reveal_when":"intern asks how soon the watch is needed or whether there is an occasion","value":"There is no occasion attached - they would happily wait six months for an authorised allocation at retail"},{"id":"existing_waitlist","label":"Already on a boutique waitlist","reveal_when":"intern asks whether the member has approached a boutique themselves","value":"They are already on a waitlist at one boutique and want to know whether the team can move it, not be told to go and register interest"}]'::jsonb, 'easy', 'Member turns cold if quoted a price with no source behind it, sent a page of resale listings instead of one recommendation, or told simply to join a boutique waitlist.', 'Establish the retail-versus-secondary position, the willingness to wait and the existing waitlist, return one verified price with the source named and an honest read on allocation, and attach the time by which the boutique will actually have been called.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 6, 1, 21, '2026-07-07'::date, 'Advita', 'Later extended: can the team get a Rolex from the store at MRP.'),
('Olympics athletics schedule + visa', 'Event-led traveller planning around one fixture', 'Global', 'Hi, {{name}}. When exactly are the athletics on at the Olympics - I want the dates and the session times, not a link. And tell me what documents you need from me for the travel visa.', '[{"id":"evening_finals","label":"Only the evening finals matter","reveal_when":"intern asks which events or which sessions the member wants to attend","value":"They only care about the sprint finals in the evening sessions - heats and morning sessions are of no interest and should not be listed"},{"id":"passport_validity","label":"Passport close to expiry","reveal_when":"intern asks about passport validity or existing travel documents","value":"Their passport expires four months after the travel dates, which is tight for the visa and needs to be flagged before anything is booked"},{"id":"second_traveller","label":"A companion is travelling","reveal_when":"intern asks how many people are travelling","value":"A companion is travelling with them and will need the identical visa paperwork prepared in parallel"}]'::jsonb, 'easy', 'Member is irritated by a schedule pasted without session times, or by being asked for visa documents across three separate messages instead of one clear list with a deadline.', 'Pin down the evening finals the member actually wants with dates and times, give the full visa document list in a single message alongside the appointment lead time, flag the passport validity risk and the second traveller unprompted, and confirm when the paperwork will be collected.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 6, 1, 22, '2026-07-07'::date, 'Advita', 'When the athletics events are happening, and the document list required from the member for the travel visa.'),
('Airport book recommendation', 'Time-poor reader who wants one pick, not a shelf', 'Shop', '{{name}} here. Flying this evening and I want something worth reading. Give me one book, not a list of ten, and send the link so I can order it.', '[{"id":"taste","label":"Narrative non-fiction only","reveal_when":"intern asks what the member has enjoyed or read recently","value":"They read narrative non-fiction only and have already worked through the obvious business bestsellers - a mainstream title will be rejected out of hand"},{"id":"physical_copy","label":"Physical copy before the flight","reveal_when":"intern asks when it is needed or offers a digital edition","value":"It has to be a physical copy in hand before the evening flight - an e-book is no use to them at all"},{"id":"six_pm_reminder","label":"Wants a reminder at six","reveal_when":"intern asks how the member would like the order confirmed or followed up","value":"Once they confirm, they want a reminder at six in the evening rather than having to chase the order themselves"}]'::jsonb, 'easy', 'Member disengages if handed five titles to choose between, or if a link arrives without the price, the format and a delivery time attached to it.', 'Uncover the non-fiction taste and the pre-flight physical-copy deadline, recommend a single title with one line on why it fits, price and a working link, place the order on confirmation and own the six o''clock reminder without being chased.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 6, 1, 23, '2026-07-07'::date, 'Advita', 'A good book to pick up at the airport, with purchase link. Member confirmed the order and asked for a reminder at 6:00 PM.'),
('Ratnagiri road trip this weekend', 'Weekend driver who wants specifics, not brochure copy', 'Global', 'Hi, {{name}} here. Thinking of driving up to Ratnagiri this weekend. How long is it from Goa, and which temples are actually worth the stop. Send me the location links as well.', '[{"id":"water_temples","label":"Wants the temples set in water","reveal_when":"intern asks what kind of temples or what the member wants from the stops","value":"They specifically want the temples that sit in water and look their best in the monsoon - a general temple list will be ignored"},{"id":"driving_limit","label":"Elderly parent in the car","reveal_when":"intern asks who is travelling or about the drive itself","value":"An elderly parent is in the car, so no single stretch beyond about four hours and a comfortable meal break has to be built in"},{"id":"first_light","label":"Leaving at first light on Saturday","reveal_when":"intern asks about timings or how the day is meant to run","value":"They leave at first light on Saturday, so temple opening hours and monsoon road conditions should decide the order of the stops"}]'::jsonb, 'easy', 'Member pushes back if drive time is quoted without monsoon and traffic conditions factored in, or if temples are named without opening hours and map links in the same message.', 'Establish the water-temple brief, the four-hour driving limit and the Saturday start, return one routed plan with realistic drive time, opening hours, a break stop and map links, and confirm it well before the weekend.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 6, 1, 24, '2026-07-07'::date, 'Advita', 'Driving time from Goa, plus good temples to visit — specifically the ones in water and beautiful during monsoon. Share location links.'),
('Airport meet & greet — cost in India', 'Straight-talking enquirer who wants the fine print', 'Global', '{{name}} here. What does an airport meet and greet actually cost in India, and what do you get for the money. And explain plainly what customs assistance means, because I have never had a straight answer on it.', '[{"id":"for_parents","label":"It is for parents travelling alone","reveal_when":"intern asks who the service is actually for","value":"It is for their parents travelling alone on an international arrival, so wheelchair support and language help matter far more than speed through the queue"},{"id":"existing_quote","label":"Holds a quote that felt steep","reveal_when":"intern asks whether the member has been quoted elsewhere or what prompted the question","value":"A provider has already quoted them a figure that felt high, and what they really want is to know whether it sits inside a fair range"},{"id":"declarable_item","label":"A declarable item is being carried","reveal_when":"intern asks why customs assistance in particular matters to them","value":"The parents are carrying a declarable high-value item, so the member wants to know exactly what the assistance can and cannot do at the green channel"}]'::jsonb, 'easy', 'Member loses interest if given a price band with no inclusions, or if customs assistance is described in vague terms that quietly overstate what it can actually do.', 'Draw out that it is for parents travelling alone with a declarable item, quote a verified price range with what is and is not included, describe customs assistance honestly including its limits, and confirm the airport and arrival details before proposing a booking.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 7, 1, 25, '2026-07-07'::date, 'Advita', 'Typical pricing and what the package includes; clarify what ''customs assistance'' actually means.'),
('Property search — South Coorg (near Virajpet)', 'Patient buyer with a precise brief and no tolerance for portal listings', 'House', 'Hi, {{name}}. I am still looking for a place in South Coorg, near Virajpet, close to my coffee estate. The one you sent as a reference has sold. Keep watching, and put me in touch with a couple of agents who genuinely work that belt.', '[{"id":"land_and_build","label":"Precise land and build specification","reveal_when":"intern asks what the member is looking for or what the reference property was","value":"Around seventy-five cents of land, roughly four thousand square feet, modern bungalow style - anything materially smaller is not worth a viewing"},{"id":"move_in_ready","label":"Move-in ready only","reveal_when":"intern asks about condition or proposes a restoration opportunity","value":"It must be move-in ready as a holiday base - nothing old or run down, and no restoration projects whatsoever"},{"id":"build_option","label":"Would consider building on the estate","reveal_when":"intern asks what happens if nothing suitable comes to market","value":"Building on their existing estate is not ruled out, so an architect or builder introduction would be welcome alongside the search"}]'::jsonb, 'easy', 'Member goes quiet if sent portal listings that ignore the size and condition brief, or if agent introductions arrive as bare names with no credentials or note on what each one actually covers.', 'Confirm the land size, build size and move-in-ready condition, introduce two or three vetted agents working that belt with credentials and context, raise the build-on-estate route unprompted, and set a standing cadence for new listings so the member never has to ask again.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 7, 1, 26, '2026-07-07'::date, 'Anishqa', 'Buyer wants a home near his coffee estate. Reference: ~75 cents (3/4 acre), ~4,000 sq ft, modern bungalow style. No old or run-down properties — must be move-in ready as a holiday base. The reference property sold; keep watching for similar. Building on his existing estate is not ruled out. Connect with a few real estate agents and share agent details.'),
('Quick-commerce onboarding partner', 'Founder who wants an introduction, not another pitch deck', 'Shop', '{{name}} here. I need someone with genuine connects across Blinkit, Zepto and Flipkart Minutes to get one of my brands listed and onboarded. A warm introduction would be far more useful to me than another agency cold pitch.', '[{"id":"cold_chain","label":"Short shelf-life category","reveal_when":"intern asks what the brand is or which category it sits in","value":"It is a chilled, short shelf-life food line, so the partner must have done cold-chain listings on these platforms before rather than dry goods"},{"id":"burned_before","label":"Two agencies have already failed","reveal_when":"intern asks what has been tried already","value":"Two agencies have taken a retainer and produced nothing but paperwork - they want evidence of real platform relationships, not another deck"},{"id":"commercials_open","label":"Retainer is open for real access","reveal_when":"intern asks about budget or engagement terms","value":"The retainer is genuinely open if the introductions are real, and they would prefer part of it linked to listings actually going live"}]'::jsonb, 'easy', 'Member disengages if handed a list of agency websites with no vetting behind it, or if introductions are promised without naming who is being approached and by when.', 'Establish the cold-chain category, the failed agency history and the open commercials, return two or three named and referenced operators with evidence of platform work, and commit to a specific time for the first warm introduction.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 7, 1, 27, '2026-07-07'::date, 'Anishqa', 'An agency or freelancer with strong connects across Blinkit, Zepto and Flipkart Minutes who can help with listings and onboarding for one of our brands. Warm intro preferred.'),
('Source product (image shared) — 2 boxes to Delhi', 'Regular sourcer who expects the customs question answered before asking it', 'Shop', 'Hi, {{name}}. Sending you a photo of what I need - two boxes of it, delivered to Delhi. It is normally only sold in Thailand, Singapore or Australia. Can you source it, and does the supplier genuinely handle customs.', '[{"id":"not_licensed","label":"Not licensed for retail sale in India","reveal_when":"intern asks why it cannot be bought locally or raises import restrictions","value":"The item is a supplement that is not licensed for retail sale in India, which is precisely why the customs question was asked in the first place"},{"id":"receive_window","label":"Must land before the member travels","reveal_when":"intern asks when it is needed in Delhi","value":"It has to be in Delhi within three weeks, before the member travels - after that there is nobody at the address to receive it"},{"id":"variant_ok","label":"Singapore pack is acceptable","reveal_when":"intern asks whether an alternative market variant or pack size would do","value":"The Singapore pack is acceptable provided the formulation matches, even though the box looks different from the photo"}]'::jsonb, 'easy', 'Member reacts badly to a supplier being named before the customs position is confirmed, or to being told it is being checked with no time attached to the revert.', 'Confirm the exact item from the image before quoting anything, surface the licensing issue, the three-week receiving window and the acceptable Singapore variant, name a supplier who verifiably clears customs with landed cost and a delivery date, and hold the tracking without the member chasing.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 7, 1, 28, '2026-07-07'::date, 'Anishqa', 'Usually available in Thailand, Singapore or Australia. Confirm whether the supplier genuinely handles customs.'),
('Attach ETAs to every request', 'Even-tempered member whose patience has just run out', 'GMR', '{{name}} here. I have four things open with your team and not one of them has a time against it. Tell me when each one is coming back to me. And from here on I want an ETA on every single reply.', '[{"id":"one_urgent","label":"Only one of the four is urgent","reveal_when":"intern asks which of the open items matters most or should be prioritised","value":"Only one of the four is genuinely needed today - the rest can wait until the end of the week quite happily, provided they are told so"},{"id":"broken_promise","label":"A previous shortly ran to two days","reveal_when":"intern asks what prompted the message or what has gone wrong","value":"They were told shortly on an earlier request and it took two days - it is the broken commitment rather than the wait itself that annoyed them"},{"id":"long_eta_fine","label":"A long ETA is fine if it is kept","reveal_when":"intern hedges on giving a firm time or worries the honest answer is too slow","value":"They would far rather be told forty-eight hours and have it honoured than be told an hour and be let down again"}]'::jsonb, 'easy', 'Member hardens if the reply is another acknowledgement with no times in it, if only some of the four items are addressed, or if a time is given and then missed without a warning message first.', 'Reply in one consolidated message with a named owner and a specific time against all four items, identify which one is genuinely urgent today, acknowledge the earlier broken commitment plainly without excuses, and give times honest enough to be kept.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 8, 1, 29, '2026-07-07'::date, 'Anishqa', 'Every response must carry an ETA — by when a revert can be expected and how much time the team needs.'),
('5 boxes of mini waffles to the office', 'Repeat small-order member who expects recall, not questions', 'House', 'Hi {{name}}. Five boxes of the mini waffles to the office please. Order them the moment I confirm, and tell me once it is actually placed.', '[{"id":"same_as_last","label":"Same order as last time","reveal_when":"intern asks which flavours or which outlet to order from","value":"It is the same mix from the same outlet as the last order the team placed - the member expects that to be on record rather than asked again"},{"id":"three_oclock","label":"Must land before a three o''clock meeting","reveal_when":"intern asks when it is needed at the office","value":"They need it at the office before a three o''clock meeting - anything arriving after that is pointless"},{"id":"reception_drop","label":"Rider goes to reception","reveal_when":"intern asks about the delivery point or who will receive it","value":"The rider must be directed to reception rather than calling the member, and reception needs the delivery name passed to them in advance"}]'::jsonb, 'easy', 'Member is unimpressed if asked which flavours were ordered last time, or if the order is placed silently and they only discover it when the rider arrives.', 'Pull the previous order from the record rather than asking, confirm the three o''clock deadline and the reception drop, place the order the moment it is confirmed, and send a single message confirming it is placed with the rider ETA on it.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 8, 1, 30, '2026-07-07'::date, 'Advita', 'Ordered on confirmation; communicate once placed.'),
('Australia 14-day trip for 2 friends', 'Well-travelled planner who dismisses anything off the first page of a search', 'Global', 'Hi, {{name}} here. Two of us, fourteen days in Australia around {{date}} - Sydney three nights, Hobart two, Melbourne three, Fiji three and Brisbane two. Hotels, where to eat, what to do. Nothing obvious please, and tell me when I will have it.', '[{"id":"fiji_flex","label":"The Fiji leg is droppable","reveal_when":"intern asks whether any leg is flexible or raises the cost of the Fiji flights","value":"Fiji is optional and can be swapped for another leg entirely if the flights are expensive or the routing is awkward"},{"id":"dates_open","label":"Travel dates are not locked","reveal_when":"intern asks whether the travel dates are confirmed","value":"The dates are not fixed - August or September both work, so the plan should be built around what is genuinely best rather than a fixed calendar"},{"id":"one_document","label":"One document with a stated delivery time","reveal_when":"intern asks how the member would like the plan delivered","value":"They want it as a single PDF or deck rather than a run of messages, and they want a stated time by which it will land"}]'::jsonb, 'easy', 'Member switches off at mainstream recommendations, at a plan trickled out in fragments across the thread, or at any reply that arrives without a stated delivery time against it.', 'Confirm the flexible dates and the droppable Fiji leg before building anything, deliver one avant-garde day-by-day plan covering hotels, restaurants, activities and intercity transport in a single document, and commit to a delivery time and honour it.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 8, 1, 31, '2026-07-07'::date, 'Ananyshree', 'Sydney 3N, Hobart (Tasmania) 2N, Melbourne 3N, Fiji 3N (optional — replace if flights are too costly), Brisbane 2N. Travel Aug/Sept, dates unconfirmed. Hotels, where to eat, activities. Avant-garde suggestions only. Compile into a single PDF or PPT and give an ETA.'),
('Read Periscope chats until 10:30 AM', 'Long-standing member who expects recall, not questions', 'GMR', 'Morning, {{name}} here. This is the third time I am raising the same thing and each time somebody starts me from the beginning. Everything is already in my thread with your team, so please read it back before you ask me a single question, and then tell me where we actually stand.', '[{"id":"standing_request","label":"What the open request actually is","reveal_when":"intern reads the history back or references the existing request instead of asking what it is","value":"The open item is a standing weekly car and driver for the school run, agreed a fortnight ago and never confirmed back."},{"id":"real_grievance","label":"The real complaint","reveal_when":"intern asks what has gone wrong rather than restating the request","value":"The request itself is trivial; being asked the same three questions by three different people is what has worn them down."},{"id":"hard_date","label":"When it must be locked","reveal_when":"intern asks by when they need it confirmed","value":"It has to be locked before Monday morning because the arrangement starts that day."}]'::jsonb, 'easy', 'Being asked for details the team already holds, or receiving an empty acknowledgement such as noted or checking with no outcome and no ETA attached.', 'Intern reads the thread first, plays the standing arrangement back accurately without re-asking anything on file, and confirms it locked ahead of the start date in one consolidated message.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 8, 2, 32, '2026-07-08'::date, 'Advita', 'Study how the senior team communicates with members before the round starts. Speak to Ethan if you do not have Periscope access.'),
('Doctor for a persistent sore throat — Goa', 'Unwell traveller, patience running thin', 'House', 'Hi, {{name}} here. I have had a sore throat for over a week now and it is not shifting. I saw a doctor here in Goa a few days ago and it made no difference at all. Who else can I see.', '[{"id":"already_medicated","label":"Already on a course of antibiotics","reveal_when":"intern asks what the first doctor prescribed or what has already been tried","value":"They are three days into a course of antibiotics with no improvement, so an ENT specialist is needed rather than another general physician."},{"id":"travel_limit","label":"Will not travel far to be seen","reveal_when":"intern asks where they are staying or how far they are willing to travel","value":"They are in North Goa and will not drive more than 40 minutes; a doctor willing to come to the villa is far preferred."},{"id":"flight_out","label":"Flying out shortly","reveal_when":"intern asks about travel plans or how urgent this is","value":"They fly out on Friday and want this resolved before they travel."}]'::jsonb, 'easy', 'Being sent a list of clinics to choose from with no recommendation, or a reply with no ETA on when a doctor will actually be confirmed.', 'Intern establishes what has already been tried and the travel limit, recommends one specialist or a house call with timing, cost and access, and confirms the appointment before the member flies out.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 9, 1, 33, '2026-07-08'::date, 'Advita', 'Over a week, already seen one doctor with no resolution. Who else can be consulted.'),
('Temple suggestion in Surat for Karan', 'Devoted son planning around an elderly parent', 'Global', 'Hello, {{name}} here. I am taking my father to Surat next week and would like to take him to a temple while we are there. Could you suggest somewhere and tell me the timings.', '[{"id":"mobility","label":"Father cannot manage steps","reveal_when":"intern asks who is visiting or about any mobility needs","value":"His father is elderly and cannot manage more than a handful of steps, so the car must be able to reach close to the entrance."},{"id":"window","label":"Very narrow visiting window","reveal_when":"intern asks when they plan to visit","value":"They only have Tuesday morning before a midday flight, so darshan timings and queue length decide everything."},{"id":"crowds","label":"Wants quiet, not a landmark","reveal_when":"intern asks what kind of visit they have in mind","value":"They would far rather a quiet, well-kept temple than the busiest landmark in the city."}]'::jsonb, 'easy', 'A bare list of temple names with no timings, no drive time and no recommendation, or being asked something about the trip they have already set out.', 'Intern surfaces the mobility limit and the narrow morning window, recommends one temple with confirmed darshan timings, drive time and vehicle access to the entrance, and offers to arrange the car.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 9, 1, 34, '2026-07-08'::date, 'Advita', 'Temple suggestion in Surat for Karan.'),
('Rolex to gift brother on his birthday', 'Exacting buyer who expects the file to be read', 'Shop', '{{name}} here. I want to gift my brother a Rolex for his birthday. Your team already has the date, the budget and where it needs to reach, so please do not ask me for any of that again. Tell me what you can actually get.', '[{"id":"on_file","label":"The brief is already on file","reveal_when":"intern offers to check the backend and plays the details back rather than asking for them","value":"The file holds a ceiling of twenty-five lakh, delivery to the member''s Mumbai residence and a birthday on Saturday at the end of the month."},{"id":"condition","label":"Condition is non-negotiable","reveal_when":"intern asks what condition or set the member expects","value":"It must be unworn with full set and papers; a pre-owned piece is refused however good the price."},{"id":"viewing_token","label":"Will pay the viewing token, on conditions","reveal_when":"intern explains the viewing terms and the advance token before asking for money","value":"They will place the non-refundable one lakh token only once they have seen photographs of the actual piece and have the tax position in writing."}]'::jsonb, 'easy', 'Being asked for the birthday date, the budget or the delivery city that the team already holds, or being quoted a price with no clarity on tax, condition or when the watch can be seen.', 'Intern reads the file back unprompted, sources a confirmed unworn piece with full set, sets out the tax position, viewing terms and non-refundable token in a single message, and commits to a delivery date ahead of the birthday.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 9, 1, 35, '2026-07-08'::date, 'Advita', 'Team is expected to already know the date, budget and delivery location rather than asking. Confirm unused, tax position, viewing before payment and delivery date. Viewing offered against a non-refundable ₹1L advance token.'),
('Gift for Rohit Sharma', 'Corporate gifter who wants proof, not research', 'Shop', 'Hi {{name}}. I need a gift for someone turning forty, budget up to two lakh. I do not want a research document from you, I want to see what is actually sitting on the shelf.', '[{"id":"recipient_taste","label":"What the recipient already owns","reveal_when":"intern asks about the recipient or what they already enjoy","value":"The recipient collects whisky and already owns most of what is commonly sold in India, so only a genuinely hard to find bottle will land."},{"id":"handover","label":"Hard handover date","reveal_when":"intern asks when and where the gift is needed","value":"It has to be wrapped and handed over at a dinner on Thursday, so anything that needs importing is useless."},{"id":"budget_flex","label":"The ceiling can stretch","reveal_when":"intern asks whether the budget is firm for the right bottle","value":"The ceiling can stretch by half again for something rare, but not for something ordinary in a nice box."}]'::jsonb, 'easy', 'Catalogue images or a generic shortlist instead of photographs of stock actually held, or a recommendation with no price and no confirmation the bottle is in the city.', 'Intern establishes the recipient''s collection and the Thursday handover, calls the retailer for photographs of real stock, and returns one verified in-stock recommendation with price, packaging and a delivery plan.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 9, 1, 36, '2026-07-08'::date, 'Advita', '40-year-old recipient, budget up to ₹2 lakh. Team to call Good Earth / an alcohol store for real photos of stock rather than sending generic research. Savio to verify the alcohol pick is good enough.'),
('US visa', 'Impatient traveller who assumes money solves it', 'Global', '{{name}} here. I need a US visa. Tell me the process, what it costs and how quickly it can be done. I am happy to pay whatever it takes if someone can guarantee it.', '[{"id":"prior_refusal","label":"Previous refusal on record","reveal_when":"intern asks about visa history or earlier applications","value":"They were refused a US visa some years ago, which changes the paperwork entirely and makes any guarantee impossible."},{"id":"real_deadline","label":"Why the timing matters","reveal_when":"intern asks what the travel is for and when","value":"There is a conference in 6 weeks that they cannot miss; every other part of the trip can move."},{"id":"third_country","label":"Open to an appointment abroad","reveal_when":"intern raises appointment availability or alternative consulates","value":"They would happily take an appointment in another country if it brings the interview date forward."}]'::jsonb, 'easy', 'Any suggestion that approval can be guaranteed, a single lump-sum figure with no split between consular fee and service fee, or a reply carrying no timeline.', 'Intern draws out the earlier refusal and the conference date, states plainly that no outcome can be guaranteed, sets out the process, the fee breakdown and realistic slot timings, and proposes the fastest legitimate route.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 10, 1, 37, '2026-07-08'::date, 'Advita', 'Process, cost, and whether the visa can be guaranteed — member is happy to pay more.'),
('Work wardrobe — stylist ideas', 'Newly promoted professional, unsure where to start', 'Shop', 'Hello, {{name}} here. I am starting a new role and my work wardrobe is nowhere near up to it. Could you put me in front of a stylist, or simply tell me what I ought to be buying.', '[{"id":"dress_code","label":"The actual dress code","reveal_when":"intern asks about the role or the environment being dressed for","value":"The role is client-facing at a private bank, so it is formal tailoring rather than smart casual."},{"id":"fit_issue","label":"Off the rack never fits","reveal_when":"intern asks about fit, sizing or previous purchases","value":"Nothing off the rack fits across the shoulders, so made-to-measure is the only route that has ever worked."},{"id":"timing","label":"The start date drives everything","reveal_when":"intern asks when it is all needed by","value":"The first day is in 3 weeks, so at least two complete outfits must be finished before then."}]'::jsonb, 'easy', 'Five stylist profiles handed over with no recommendation, or shopping suggestions offered before anyone has asked what the role or the fit problem is.', 'Intern uncovers the formal client-facing dress code, the fit problem and the start date, recommends one stylist with credentials, fee and first appointment, and maps a made-to-measure timeline that lands before day one.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 10, 1, 38, '2026-07-08'::date, 'Advita', 'Work wardrobe — stylist ideas.'),
('Cook for home — share profiles', 'Household manager who wants the standard pack, quickly', 'House', 'Hi, {{name}} here. We need a cook for the house. Please send across the profiles you have.', '[{"id":"diet","label":"Strict kitchen rules","reveal_when":"intern asks about the household''s food or kitchen requirements","value":"The household is strictly vegetarian with no onion or garlic, and the cook must be comfortable cooking that way every day."},{"id":"terms","label":"Shape of the role","reveal_when":"intern asks about hours, live-in or live-out, and household size","value":"It is live-out, six days a week, for a family of 5 with guests most weekends."},{"id":"urgency","label":"Why it is being asked now","reveal_when":"intern asks when the cook is needed to start","value":"The current cook leaves at the end of the month, so profiles are needed this week and interviews the week after."}]'::jsonb, 'easy', 'A round of questions before anything is sent, or profiles dribbled out as loose messages rather than the standard house staff pack with an ETA.', 'Intern sends the standard house staff profile document promptly with a clear ETA for the shortlist, confirms the no onion or garlic requirement and the live-out terms, and books interviews before the current cook leaves.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 10, 1, 39, '2026-07-08'::date, 'Advita', 'Send the standard house-staff PDF; Savio to make sure the team knows which document to send.'),
('Live-in physiotherapist + yoga instructor — Vijayapura, Karnataka', 'Family organiser, thorough and specific', 'House', 'Hello, {{name}} here. We are looking for a live-in physiotherapist who can also teach yoga, based at our residence in Vijayapura in Karnataka. Full-time and permanent, with accommodation, meals and essentials provided. Please share profiles with qualifications, experience, expected salary and availability.', '[{"id":"patient","label":"Who the sessions are actually for","reveal_when":"intern asks who will be receiving the daily sessions","value":"The sessions are for the member''s mother, who had a knee replacement 3 months ago, so post-operative physiotherapy experience is essential."},{"id":"household_pref","label":"Preference for a live-in role","reveal_when":"intern asks whether the household has any preference on the practitioner","value":"A female practitioner is strongly preferred given the live-in arrangement at a family residence."},{"id":"package","label":"Salary is negotiable","reveal_when":"intern asks about the salary band or how flexible the package is","value":"The band is negotiable for someone genuinely qualified in both disciplines, and relocation costs would be covered."}]'::jsonb, 'easy', 'Profiles that cover only yoga or only physiotherapy, or being asked again for the location and terms already set out in the first message.', 'Intern confirms the post-operative requirement and the household preference, returns a shortlist of dual-qualified candidates with credentials, salary expectations and start dates by a stated time, and arranges interviews.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 10, 1, 40, '2026-07-08'::date, 'Anishqa', 'Full-time, live-in, permanent position at a private residence. Must be qualified in both physiotherapy and yoga, able to run daily sessions for health, mobility, flexibility and wellness. Accommodation, meals and essentials provided. Share profiles, qualifications, experience, expected salary and availability at the earliest.'),
('Female speech therapist — Gurgaon', 'Anxious parent who needs someone starting immediately', 'House', 'Hi, {{name}} here. I need a female speech therapist for my 3 year old, home sessions in Gurgaon, an hour at a time and evenings if possible. Ideally starting tomorrow. Could you send profiles, credentials and session charges.', '[{"id":"assessment","label":"There is already an assessment","reveal_when":"intern asks whether the child has been assessed or seen anyone before","value":"A paediatrician has already diagnosed a speech delay and there is an assessment report the therapist should read before the first session."},{"id":"language","label":"Bilingual household","reveal_when":"intern asks what language the sessions should be conducted in","value":"Both English and Hindi are spoken at home, so the therapist must be comfortable working across the two."},{"id":"premium","label":"Will pay for immediacy","reveal_when":"intern asks how firm the start date is or raises availability","value":"They will pay a premium for someone who can start within 2 days rather than wait for a better-known name."}]'::jsonb, 'medium', 'Profiles sent without charges or availability, a male therapist proposed after the requirement was stated, or no confirmed time given for when the shortlist will land.', 'Intern captures the existing assessment and the bilingual requirement, returns two vetted female therapists with credentials, session charges and confirmed evening availability, and locks a first session inside the member''s window.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 11, 1, 41, '2026-07-08'::date, 'Anishqa', 'Child aged 3, Sector 58 Gurgaon, home sessions, 1 hour, evening preferred, starting today or tomorrow. Female therapist only, experienced with young children. Share profiles, credentials, experience and session charges.'),
('Table for 2 at Naru — 8:00 PM today', 'Casual ask carrying an unforgiving deadline', 'Global', 'Hi {{name}}. Table for 2 tonight at 8, the small ramen counter in Bengaluru, the one that only does a couple of seatings. Can you get it done.', '[{"id":"no_bookings","label":"The venue does not take bookings","reveal_when":"intern verifies the venue''s policy or availability before promising anything","value":"The counter takes no reservations at all and runs a queue, so the only real answer is a token and a realistic arrival time."},{"id":"timing_flex","label":"The time flexes, the venue does not","reveal_when":"intern asks whether the time or the restaurant can move","value":"They will happily take 7 or 9.15 at that counter, but will not be sent somewhere else instead."},{"id":"dietary","label":"One guest cannot eat gluten","reveal_when":"intern asks about dietary needs","value":"One of the two is coeliac and needs to know in advance whether that kitchen can handle it."}]'::jsonb, 'medium', 'Confirming a table without checking whether the venue even takes bookings, or offering three alternative restaurants instead of solving the one that was asked for.', 'Intern verifies that the counter runs a queue rather than reservations, secures a token and an arrival time inside the member''s window, checks the kitchen on gluten, and confirms the lot in one message.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 11, 1, 42, '2026-07-08'::date, 'Advita', 'Table for 2 at Naru — 8:00 PM today.'),
('Mini Kelly and Birkin — options', 'Collector''s spouse, quietly exacting', 'Legacy', 'Good afternoon, {{name}} here. I am looking for a Mini Kelly and a Birkin. Show me what is genuinely available rather than what might be.', '[{"id":"occasion","label":"Who each piece is for","reveal_when":"intern asks about the occasion or the timing","value":"One is for the member''s wife''s birthday in 3 weeks; the other is an investment piece with no deadline at all."},{"id":"colour","label":"Colour must not repeat","reveal_when":"intern asks about existing pieces or colour preferences","value":"She already owns a black one, so a repeat colour is out; a soft neutral or a green would be welcomed."},{"id":"provenance","label":"Provenance decides the purchase","reveal_when":"intern raises authentication, condition or paperwork","value":"Pre-loved is acceptable if unworn, but only with box, receipt and independent authentication, and only after photographs of the actual bag."}]'::jsonb, 'medium', 'A wall of stock images with no prices, no condition notes and no recommendation, or claimed availability that cannot be evidenced with photographs of the actual piece.', 'Intern surfaces the birthday timing, the colour rule and the provenance requirement, returns two evidenced options with real photographs, condition, paperwork and landed price, and recommends one of them.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 11, 1, 43, '2026-07-08'::date, 'Advita', 'Mini Kelly and Birkin — options.'),
('Dinner in Baku tonight', 'Arriving traveller who wants tonight solved and tomorrow teed up', 'Dubai', '{{name}} here. Dinner in Baku tonight for 2 please, halal only. Send me the cuisine and the menu, and tell me what the party scene looks like there tonight.', '[{"id":"arrival","label":"They land late","reveal_when":"intern asks what time they want to eat or when they land","value":"They land late in the evening, so nothing before half past nine is any use to them."},{"id":"alcohol","label":"One guest does not drink","reveal_when":"intern asks about preferences or who is dining","value":"One of the two does not drink at all, so an alcohol-led venue would be uncomfortable for both of them."},{"id":"party_scene","label":"The nightlife ask is for another night","reveal_when":"intern clarifies which night the nightlife question is really about","value":"Tonight is dinner only after a long flight; the party scene question is genuinely for Saturday."}]'::jsonb, 'medium', 'Five venue names with no halal confirmation, no menu and no distance from the hotel, or nightlife pushed at them on the night they land exhausted.', 'Intern confirms the late arrival and the guest who does not drink, recommends one verified halal restaurant with cuisine, menu, distance from the hotel and a table held after half past nine, and parks the nightlife brief for the following evening.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 11, 1, 44, '2026-07-08'::date, 'Advita', '2 people. Confirm halal menu availability, cuisine and menu. Also: what is the party scene in Baku tonight.'),
('Order a decaf coffee', 'Brisk member testing whether small things are done properly', 'Global', '{{name}} here. Order me a decaf coffee please. The usual.', '[{"id":"medical","label":"Decaf is not a preference","reveal_when":"intern confirms the decaf requirement with the cafe rather than assuming it","value":"They are on medication that rules out caffeine entirely, so a half-caff or a low-caffeine blend is not acceptable."},{"id":"on_file","label":"The order is already on file","reveal_when":"intern offers to check the backend instead of asking for the details","value":"The file already holds the usual order, oat milk and no sugar, and the daytime delivery location."},{"id":"timing","label":"There is a clock on it","reveal_when":"intern asks by when it needs to arrive","value":"It needs to be on the desk before a call at 4, and a late delivery is worse than no delivery."}]'::jsonb, 'medium', 'Being asked which cafe, which milk and where to send it when all three sit on file, or the order being placed and then left untracked until the member chases.', 'Intern reads the standing order from the file, confirms genuine decaf with the cafe, places the order to land ahead of the call, and confirms arrival without being chased.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 12, 1, 45, '2026-07-08'::date, 'Advita', 'Order a decaf coffee.'),
('Morning flight to Ahmednagar — Sunday', 'Frequent flyer with fixed habits', 'Global', 'Hi, {{name}} here. I need a morning flight on Sunday to get me to Ahmednagar. Book it and send me the details.', '[{"id":"routing","label":"How they always do this route","reveal_when":"intern checks travel history or asks how they have made this trip before","value":"Ahmednagar has no airport; they always fly into Pune and take a car onward, and that routing is already sitting in their history."},{"id":"no_layover","label":"Connections are refused outright","reveal_when":"intern proposes a routing or asks about flight preferences","value":"They will not take a connecting flight under any circumstances and would rather leave at first light on a direct."},{"id":"arrival_deadline","label":"Why the morning matters","reveal_when":"intern asks when they need to be on the ground","value":"There is a family function at 2 in the afternoon, so they must land by noon with the drive allowed for."}]'::jsonb, 'medium', 'A one-stop itinerary being sent across, or being asked which airport to fly into when the routing is already in their history.', 'Intern checks the history first, proposes a direct morning flight into Pune with a car arranged onward, shows arrival and drive times against the afternoon deadline, and books once confirmed.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 12, 1, 46, '2026-07-08'::date, 'Advita', 'Never send a layover flight. Check history — do Goa–Pune and the member takes a cab onward.'),
('Close every open task on a call', 'Senior member who wants outcomes, not status reports', 'GMR', '{{name}} here. I have half a dozen things open with your team and no idea where any of them stand. One person, one message, every item closed out. Outcomes please, not checking.', '[{"id":"already_done","label":"Two items are quietly finished","reveal_when":"intern works through each open item from the record rather than asking the member to list them","value":"Two of the open items were completed days ago and simply never confirmed back, which is why the member believes nothing is moving."},{"id":"priority","label":"Only two things matter today","reveal_when":"intern asks which items matter most today","value":"Only the travel booking and the gift delivery matter before this evening; the rest can wait until Monday."},{"id":"format","label":"One message, not a thread","reveal_when":"intern proposes how they intend to report back","value":"A stream of separate updates will annoy them further; they want one consolidated message with an owner and a time against each item."}]'::jsonb, 'medium', 'Fragmented updates across several messages, any item reported as checking or shortly with no outcome and no time, or the member being asked to list their own open requests.', 'Intern reconstructs every open item from the record, closes out the two already completed, gives an outcome or a firm ETA on the rest, and delivers it as a single consolidated message ordered by what matters today.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 12, 1, 47, '2026-07-08'::date, 'Advita', 'One person to call and close out all tasks one after another. Outcomes, not reports.'),
('Chennai weather update for today', 'Terse early riser, wants the answer not the source', 'Global', 'Morning, {{name}} here. What is the weather doing in Chennai today? Quick one.', '[{"id":"evening_window","label":"Only the evening matters","reveal_when":"intern asks what the weather is for or which part of the day matters","value":"There is an open-air rooftop dinner at seven this evening - the daytime forecast is irrelevant, the evening rain risk is the entire question"},{"id":"cabin_only","label":"Travelling with cabin baggage only","reveal_when":"intern asks whether they are travelling in or need packing guidance","value":"Landing at midday with hand luggage only, so an umbrella and a change of linen would have to be bought on arrival"}]'::jsonb, 'medium', 'A screenshot of a weather app or a bare daily high and low, with no read on the evening and no ETA attached.', 'Surfaces the rooftop dinner and the cabin-only arrival, then returns one message with the hour-by-hour evening rain risk and humidity, a clear call on whether the rooftop holds, a covered fallback and what to carry.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 12, 2, 48, '2026-07-09'::date, 'Advita', 'Chennai weather update for today.'),
('Sunday plan in Goa', 'Sociable solo traveller, wants a plan not a list', 'Global', 'Hi, {{name}} here. I have Sunday free in Goa and want to make something of it. Somewhere proper for lunch, and I have been meaning to do a Bollywood or jive workshop if anything is running.', '[{"id":"dining_alone","label":"Attending on their own","reveal_when":"intern asks who is joining or how many covers to book","value":"Going alone, so a bar seat or a communal table suits far better than a formal table laid for one"},{"id":"jive_preferred","label":"Jive over Bollywood","reveal_when":"intern asks which of the two workshops they would rather do","value":"Would much rather do jive - two beginner Bollywood classes already done and both felt repetitive"},{"id":"free_by_six","label":"Must be free by early evening","reveal_when":"intern asks how the day should be shaped or when they need to be finished","value":"There is a call at six, so lunch and the workshop have to sit close together in the same part of North Goa"}]'::jsonb, 'medium', 'Five restaurant links and a couple of workshop listings sent across for the member to choose between, with no confirmation the class actually runs on a Sunday.', 'Establishes that they are dining alone, would prefer jive and must be free by early evening, then returns a single Sunday plan with a named lunch and a seat that suits eating alone, a jive class verified as running with time and cost, and the travel between the two.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 13, 1, 49, '2026-07-09'::date, 'Advita', 'Good lunch places plus a Bollywood or jive workshop for Sunday. Single member attending.'),
('Quirky gift — 22–23 year old woman', 'Gift-giver who wants taste, not a shopping list', 'Shop', 'Hi, {{name}} here. I need a gift for a girl turning twenty-three on Saturday. She is enormous fun, lives inside her K-dramas and is very particular about clothes. It has to feel thoughtful, and I am in Goa.', '[{"id":"budget_ceiling","label":"Firm five thousand ceiling","reveal_when":"intern asks what they would like to spend","value":"Five thousand rupees is a hard ceiling rather than a guide - anything above it will be declined outright"},{"id":"friday_cutoff","label":"Must land Friday evening","reveal_when":"intern asks when and where it needs to be handed over","value":"It is given on Saturday morning, so it has to be in Goa by Friday evening - a Saturday delivery slot is already too late"},{"id":"rejected_categories","label":"Obvious gifts already used","reveal_when":"intern proposes perfume, chocolates or a voucher","value":"Perfume, chocolate and gift cards have all been given before and will read as lazy"}]'::jsonb, 'medium', 'A perfume or a voucher proposed without a single discovery question, or a shortlist handed over with no recommendation and no confirmation it can reach Goa in time.', 'Draws out the five thousand ceiling, the Friday-evening cut-off and the categories already burned, then recommends one quirky, well-argued gift with its cost, where it is coming from and a delivery ETA that clears Friday.', '{"comprehension":1,"brand_tone":1,"factual_accuracy":1.5,"proactivity":1,"escalation_judgment":1,"closure":1}'::jsonb, 13, 1, 50, '2026-07-09'::date, 'Ananyshree', 'Fun-loving, watches K-drama, into fashion, likes to party. Needs to feel very thoughtful. In Goa, under ₹5,000, by Saturday.'),
